        "평가사유": "[화제성 10점] (확정 →) 개최일·장소·시간 확정: 현지 11/14(토) 14:00 ET 브루클린 바클리스 센터, 한국시간 11/15(일) 04:00. e스포츠 연간 최대 시청 이벤트이고 LCK 팀 진출 시 국내 화제성이 전 종목 최상급으로 올라간다(진출팀은 녹아웃 결과에 연동 → 추정).\n[독창성 7점] (추정 →) 라이엇 주관 대회로 중계 자체는 공개 스트리밍이라 독점 확보는 불가하지만, 자사 연관 구단(한화생명e스포츠) 출전 가능성이 차별적 콘텐츠 가치를 만든다(실무자 보정 원칙 5 — 보유 구단 존재 시 독창성 가점).\n[근접성 4점] (확정 → 검증 단계 정정) 현지 킥오프가 토요일 '저녁'이 아니라 오후 2시(ET)여서 한국시간으로는 일요일 오전~낮이 아니라 **새벽 4시**다. 실무자 보정 원칙 1(새벽·심야 중계는 근접성 3~5)을 그대로 적용해 6점→4점으로 내렸다. 녹아웃 스테이지(근접성 5, '새벽~오전')보다도 한 단계 불리하다. LCK 팀 진출도 미확정.\n[영향성 7점] (추정 →) 국내 e스포츠 담론을 지배하는 이벤트이고 자사 구단 서사와 연결되면 브랜드 기여도 크다.\n[종합] 강점 e스포츠 최대 결승·일요일이라 새벽에도 시청 부담이 상대적으로 덜함·자사 연관 구단 서사 / 약점 LCK 팀 진출 미확정(탈락 시 화제성 급락)·중계 독점 불가 / 편성: 이번 회차 최우선 편성 검토 대상, 진출 결과에 따른 플랜 A/B 필요",
