        "개요": "레알 마드리드 홈구장 베르나베우에서 열리는 NFL 경기. 2026시즌 NFL은 4대륙 7개국 8개 구장에서 역대 최다 9경기의 국제경기를 치르며, 마드리드 개최는 그 중 한 경기다.",
