        "평가사유": "[화제성 10점] (확정 →) 무라카미 하루키의 신작 장편 『가호』 한국어판(홍은주 옮김)이 문학동네에서 2026년 10월 출간. 『도시와 그 불확실한 벽』 이후 3년 만의 16번째 장편이며, 일본에서는 2026년 9월 3일 출간 후 **발매 4일 만에 발행 부수 30만 부, 오리콘 소설 차트 3주 연속 1위**를 기록했다. 한국어판 판권 계약 자체가 2026-08-25 서울신문·한국경제 등 주요지에 단독 기사로 보도됐고, 알라딘 판매지수 231,670으로 이번 배치 전 품목 중 압도적 1위. 하루키가 여성 인물을 단독 주인공으로 내세운 첫 소설이라는 점도 추가 화제를 만들었다.\n[독창성 4점] (독점성·희소성·차별 기획 관점) 전 매체가 출간 즉시 일제히 다루는 대형 공개 아이템이라 독점 확보가 사실상 불가능하다. 작가 내한·인터뷰 가능성도 사실상 없다. 다만 '발매 전 선제 조명'이라는 타이밍 차별은 가능해 3점대를 소폭 상회하는 수준으로 본다.\n[근접성 8점] (한국 독자 친숙도·주제 대중성·접근성) 하루키는 국내에서 가장 두터운 번역문학 팬층을 가진 작가로, 신작은 출간 즉시 종합 베스트셀러권에 진입하는 것이 거의 관례다.\n[영향성 9점] (판매·의제화·영상화 연계·브랜드 기여) 대형 판매가 확실하고 출판계·문화면 의제를 주도한다. 일본 30만 부 실적상 2차 콘텐츠 연계 가능성도 열려 있다.\n[종합] 강점: 이번 배치에서 유일한 전국민 단위 화제작, 지표·보도 근거가 모두 확정. 약점·리스크: 독점 각도가 없어 모든 매체가 같은 날 같은 내용을 다룬다. 편성 관점 — 출간일 전 선제 기획(일본 반응·번역가 섭외·하루키 독자 현상)으로 차별화해야 의미가 있다.",
