        "개요": "2026년 10월 9일, 한글날 100주년을 기념하며 네이버와 민음사가 『한글』을 펴냈다. 네이버 ‘한글한글아름답게’ 캠페인과 민음사 인문잡지 《한편》은 ‘오늘의 한글 사용자’에게 이렇게 물었다. “한글의 아름다움을 언제 느끼나요?”",
        "평가사유": "[화제성 8점] (확정 →) 10월 9일 한글날 100주년 기념 민음사 특별판 에세이로, 데이식스(DAY6) 영케이가 저자로 참여한 사실이 2026-10-01 연예 매체로 보도돼 팬덤 기반 화제가 선행했다. 작사가 김이나, 국어학자 최경봉·안대회 등 필진 구성도 넓다. 민음사 인문잡지 『한편』과 네이버 '한글한글 아름답게 2026' 캠페인 협업. 알라딘 판매지수 8,120으로 이번 배치 국내 신간 중 상위.\n[독창성 5점] (독점성·희소성·차별 기획 관점) 한글날 100주년은 모든 매체가 동시에 다루는 공개 의제라 소재 자체의 독점은 불가. 다만 아이돌 멤버가 참여한 인문 단행본이라는 조합이 희소하고, 필진 섭외로 우리만의 각도를 만들 여지는 있다.\n[근접성 8점] (한국 독자 친숙도·주제 대중성·접근성) '한글'은 전 국민적 소재이고 한글날 100주년이라는 시의성이 최고조다. 대형 서점 기획 매대 노출이 사실상 확정.\n[영향성 7점] (판매·의제화·영상화 연계·브랜드 기여) 한글날 100주년 기획 보도와 직결돼 채널 기획과 맞물리기 좋고, 저자 라인업상 출연 섭외·낭독 코너 등 연계 콘텐츠 제작이 용이하다.\n[종합] 강점: 100주년 시의성 + 아이돌 참여로 세대 확장. 약점·리스크: 기념 앤솔러지 특성상 내용 밀도가 고르지 않을 수 있고, 한글날(10/9)이 지나면 소비 수명이 급감한다. 편성 관점 — 한글날 당일 전후 1주가 유일한 타이밍, 영케이·김이나 섭외 가능 여부가 성패를 가른다.",
