        "개요": "대한민국 만화가 최초로 ‘만화계의 오스카’ 하비상을 수상하고, 프랑스 문화예술공로훈장 슈발리에를 수훈한 한국 그래픽노블의 대가 김금숙이 ‘여순항쟁 이야기’로 돌아왔다. 저자 스스로 ‘영혼을 갈아서 만든 작품’이라고 칭할 만큼 몸과 마음을 쏟아부어 그려낸 신작 『흰 신』은 10·19 여수·순천 민중항쟁을 그려낸 한국 출판계 최초의 만화다.",
