        "개요": "한국 경영계의 신화를 이룬 차석용 회장의 책이다. 그가 이 책을 쓰게 된 것은 단순히 자신의 성공을 말하기 위해서가 아니다. 화려한 업적보다 그 결과를 만들기까지의 과정을 통해 자신의 뒤를 이을 다음 세대에 무엇을 원칙으로 삼고 나아가야 하는지 통찰을 전해 주기 위함이다. 그는 이 책에서 성과를 자랑하기보다 그 길을 걸으며 배운 마음가짐을 기록했다.",
        "평가사유": "[화제성 5점] (확정 →) 열린책들 2026년 10월 출간. 저자 차석용은 쌍용제지·한국P&G·해태제과를 거쳐 **LG생활건강을 18년간 이끌며 재임 중 매출을 9배로 키운 전문경영인**이자 현 휴젤 회장이다. 한국경제(2026-09-30)가 '28년 CEO 차석용을 만든 말들'로 출간을 다뤘다. 경영계 인지도는 높으나 일반 대중 인지도는 중간 수준이고, 알라딘 판매지수 480으로 아직 초기다.\n[독창성 6점] (독점성·희소성·차별 기획 관점) 재임 중 거의 인터뷰를 하지 않았던 경영인의 **첫 본격 회고**라는 점에서 희소하고, 출간 시점에 맞춘 단독 인터뷰를 확보하면 타 매체가 따라오기 어렵다.\n[근접성 5점] (한국 독자 친숙도·주제 대중성·접근성) LG생활건강·후·더페이스샵 등 익숙한 브랜드 이야기가 들어가 접근성은 있으나 경제경영 독자 중심.\n[영향성 6점] (판매·의제화·영상화 연계·브랜드 기여) M&A 중심 성장 전략은 경제 프로그램 의제로 전환하기 좋고, 저자 섭외 시 채널 신뢰도 기여가 크다.\n[종합] 강점: 섭외 성사 시 독점성이 분명한 거물 CEO 회고. 약점·리스크: 판매 규모는 경제경영 한정, 저자가 인터뷰에 응할지 불확실. 편성 관점 — 경제 코너 단독 인터뷰로 강력 추천.",
