        "개요": "섬세한 감각과 날렵한 문장, 슬픔 속에서도 웃음을 길어 올리는 시선으로 사랑받아온 소설가 김애란. 그의 첫 장편소설 『두근두근 내 인생』(창비)이 리마스터판으로 새롭게 출간되었다. 김애란은 이번 판본을 위해 작품 전체를 다시 읽으며 문장 하나하나를 살피고 매만졌다.",
        "평가사유": "[화제성 6점] (확정 →) 김애란의 『두근두근 내 인생』(2011) 리마스터판이 2026-10-08 창비에서 출간. 원작은 50만 부 이상 판매된 한국소설 대표 스테디셀러이고 2014년 영화화(강동원·송혜교)도 된 검증된 IP다. 저자가 전면 개고하고 새 작가의 말을 더했다는 점은 확인되나, **신작이 아니라 재출간**이므로 신규 화제의 폭은 제한적이다.\n[독창성 3점] (독점성·희소성·차별 기획 관점) 서점·언론·북튜브가 일제히 다루는 리마스터 재출간이고 독점 공개 요소가 없다. 저자 단독 인터뷰를 확보하지 못하면 차별점이 사실상 없다.\n[근접성 7점] (한국 독자 친숙도·주제 대중성·접근성) 이미 널리 읽힌 작품이라 인지도·정서적 친숙도가 매우 높고, 영화를 통한 2차 인지도까지 있다.\n[영향성 5점] (판매·의제화·영상화 연계·브랜드 기여) 판매는 안정적이겠으나 영상화는 이미 소진됐고 새 의제를 만들지 못한다.\n[종합] 강점: 50만 부 스테디셀러 + 저자 개고라는 명분. 약점·리스크: 신작 발굴이라는 파이프라인 취지와 어긋나는 재출간물이다. 편성 관점 — 김애란 인터뷰를 단독으로 확보할 수 있을 때만 성립. 아니면 '리마스터 출판 트렌드' 묶음용.",
