        "평가사유": "[화제성 4점] (확정 →) 창비 2026-10-05 출간, 정가 23,000원. 부제 '정수일 평전'. 변호사인 저자 차병직이 정수일 선생의 마지막 20년을 동행하며 모은 증언·자료로 일생을 재구성했다. 정수일(필명 무함마드 깐수) 사건은 1996년 간첩 혐의 적발로 당시 큰 파장을 낳았으나, 2026년 현재 2030 세대 인지도는 낮다. 알라딘 판매지수 410으로 유통 신호는 약하다.\n[독창성 6점] (독점성·희소성·차별 기획 관점) 정수일 본인과 20년을 동행한 저자가 쓴 최초의 본격 평전이라는 점에서 자료 희소성이 높고, 저자 섭외 시 다른 매체가 따라오기 어려운 증언을 확보할 수 있다.\n[근접성 5점] (한국 독자 친숙도·주제 대중성·접근성) 20세기 분단·냉전사를 통과한 개인사라는 주제는 중장년 독자에게 공감대가 있으나 젊은 층에는 거리가 있다.\n[영향성 5점] (판매·의제화·영상화 연계·브랜드 기여) 판매 규모는 제한적이나, 한 인물의 생애를 통해 분단·냉전 의제를 꺼낼 수 있고 다큐멘터리 연계 소재로서의 잠재력이 있다.\n[종합] 강점: 20년 동행 증언이라는 대체 불가 자료, 저자 섭외 가능. 약점·리스크: 대중 인지도·판매 신호가 모두 약하다. 편성 관점 — 다큐·심층 인터뷰 포맷에 적합, 일반 책 소개 코너에는 무겁다.",
