        "개요": "인간의 손을 떠나 알고리즘이 붓을 들고, 원본 작품이 전소되어 사라지는 예술적 대혼란의 시대에 미술사의 운명을 바꾼 드라마틱한 법정 기록을 통해 100년의 창작 전쟁을 들여다본다. 글로벌 문화예술 현장에서 활동하며 ‘예술법’이라는 개념을 국내 예술계와 학계·법조계에 소개했다는 평가를 받는 변호사 캐슬린 김의 첫 예술 에세이다.",
