        "개요": "변화 속에서도 계속 기회를 만드는 사람은 무엇이 다를까? 이 책은 SURVIVE, 7가지 힘을 통해 불확실한 시대에도 스스로 가능성을 넓혀가는 법을 알려준다. 직업을 지키는 법이 아니라, 어떤 변화 앞에서도 다시 기회를 만들어내는 사람으로 살아가기 위한 커리어 안내서다.",
        "평가사유": "[화제성 5점] (확정 →) 김영사 2026-10-13 출간, 저자 이찬 서울대 교수. 부제 'AI 시대에 기회를 만드는 7가지 힘'. **서울신문이 2026-10-01 '내 일자리도 사라질까… 서울대 이찬 교수가 제시한 AI 시대 생존법'으로 비중 있게 다뤘고**, 저자는 서울대에서 진로·커리어를 연구하며 국내외 대기업 인재개발 자문을 해 온 이력이 확인된다. 다만 알라딘 판매지수 110으로 초기 유통 신호는 아직 약하다.\n[독창성 4점] (독점성·희소성·차별 기획 관점) 'AI 시대 생존 역량'은 경쟁서가 많지만, 서울대 교수·기업 자문이라는 저자 포지션이 섭외 매력을 만든다. 'SURVIVE' 7역량이라는 정리된 프레임도 방송 구성에 유리하다.\n[근접성 6점] (한국 독자 친숙도·주제 대중성·접근성) 일자리 불안은 전 연령 공통 관심사로 체감 거리가 가깝다.\n[영향성 5점] (판매·의제화·영상화 연계·브랜드 기여) AI 고용 충격 의제와 직접 맞물리고, 전문가 패널로서 활용도가 높다.\n[종합] 강점: 주요지 보도라는 확정 근거 + 섭외 용이한 전문가 저자 + 프레임화된 구성. 약점·리스크: 동일 주제 경쟁서가 많아 변별이 필요하고 판매 신호는 아직 초기. 편성 관점 — AI 고용 코너 전문가 출연으로 추천.",
