        "개요": "헤르만 헤세에게 삶이란 결국 자기 자신에 이르는 여정이다. 이 책은 우리보다 앞서 그 길을 걸었던 헤세가 평생에 걸쳐 찾아낸 삶의 기술을 한 권에 담았다. 20년 넘게 헤세, 카프카, 쇼펜하우어, 니체의 책을 번역해온 독문학자 홍성광이 소설부터 에세이, 시, 편지에 이르기까지 헤세 사유의 정수가 담긴 글들을 엄선해 옮기고, ‘자기 자신에 이르는 일곱 개의 길’로 새롭게 엮었다.",
