        "개요": "미친 듯이 돌풍이 부는 날 하늘에서 떨어진 한 남자. 추락한 비행기의 잔해에서 의식을 잃은 채로 발견돼 병원에 실려 온 남자는 ‘환자 X’로 불린다. 이름도, 나이도, 국적도, 심지어 얼굴마저도 붕대에 가려져 잃어버린 ‘환자 X’의 정체를 세 인물이 각자의 방식으로 추적해나간다.",
        "평가사유": "[화제성 4점] (확정 → 출간 / 추정 → 화제) 휴머니스트 출판그룹이 2026-10-12 카렐 차페크의 '철학 3부작'(『호르두발』·『별똥별』·『평범한 인생』, 1933~34)을 **정보라 옮김**으로 동시 출간. 역자 정보라는 『저주토끼』로 부커상 인터내셔널 최종후보에 오른 작가이자 러시아·동유럽 문학 전공자로, 번역자 자체가 화제 요인이다. 다만 알라딘 판매지수 110~310으로 유통 신호는 아직 미미하다.\n[독창성 5점] (독점성·희소성·차별 기획 관점) 체코어 직역으로 3부작을 한 번에 묶어 내는 기획은 희소하고, **역자 정보라 섭외**라는 분명한 차별 각도가 있다. 다만 기존 열린책들 판본이 존재해 '최초 소개'는 아니다.\n[근접성 4점] (한국 독자 친숙도·주제 대중성·접근성) 차페크는 'robot'의 어원(R.U.R.)으로 알려졌을 뿐 소설 독자층은 두텁지 않다.\n[영향성 4점] (판매·의제화·영상화 연계·브랜드 기여) 판매 규모는 작지만 '번역가 정보라'라는 앵글로 문학 코너 기여도가 있다.\n[종합] 강점: 3부작 동시 출간 + 역자 네임밸류라는 섭외 각도. 약점·리스크: **기존 번역본이 있어 신규성이 제한되고**, 3권 동시 출간이라 개별 작품의 변별이 약하다. 편성 관점 — 3권 묶어 '정보라가 옮긴 차페크' 단일 꼭지로 구성 권장.",
