        "개요": "봄, 여름, 가을, 겨울 사계절에 일상에서 자주 보고 접했던 24종의 친숙한 채소들을 누구나 쉽게 색칠하며 즐길 수 있도록 만든 채소 컬리링북이다. 봄의 완두콩과 시금치, 여름의 오이와 토마토, 가을의 고추와 호박, 추운 겨울 더욱 맛이 깊어지는 배추와 무까지, 다양한 채소들을 자세히 관찰하고 그림 하나하나에 나만의 색을 담아 줄기와 잎, 뿌리와 열매가 어떻게 표현되었는지 살펴보면서 색칠할 수 있도록 구성하였다.",
