        "평가사유": "[화제성 9점] (일자 확정 / 동원은 추정 →) 광안대교를 배경으로 하는 국내 최대 불꽃축제. 예년 100만 명 내외가 광안리·이기대·동백섬에 몰리는 전국구 명물 이벤트로, 티켓 예매(9/4 오픈)와 숙박 대란이 매년 전국 뉴스가 된다. 100만은 주최·경찰 추산 기반 추정.\n[독창성 8점] (영상 소재성/제휴) 불꽃 연출은 대체 불가한 압도적 영상 소재이고 생중계·협찬·좌석 제휴가 실제로 성립하는 몇 안 되는 행사다. 2026년은 좌석 예약 시스템 개편·글로벌 불꽃 명장 초청이라는 신규 요소도 있다.\n[근접성 7점] 부산 개최로 물리적 거리는 있으나 전국민 친숙도가 매우 높고 해변 무료 관람구역이 넓다. 유료 좌석은 경쟁이 치열.\n[영향성 8점] 전국 동시 주목 + 부산 관광·숙박 경제에 미치는 파급이 크고 채널 위상 기여도 높다.\n[종합] 강점: 명물성·영상 소재성·중계 제휴 가능성 모두 최상급. 약점·리스크: ★단일일 야외 행사로 우천·강풍 순연 리스크가 구조적, 관람객 밀집 안전관리 이슈, 유료 좌석 암표·리셀 논란. 편성: 이번 회차 최우선 확보 대상 — 생중계·협찬 협의를 즉시 진행.",
